import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const toDispose = [];

  // Create and add textured plane from imageUrl
  if (config.assets?.imageUrl) {
    const planeGeometry = new THREE.PlaneGeometry(1, 1);
    const texture = ctx.textureLoader.load(config.assets.imageUrl);
    const material = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
    });

    const plane = new THREE.Mesh(planeGeometry, material);
    group.add(plane);

    toDispose.push(planeGeometry, material, texture);
  }

  // Render text "Pricing" via fontAtlas
  if (config.textContent) {
    let textString = config.textContent;

    // Handle various textContent formats
    if (!textString || typeof textString !== 'string') {
      if (Array.isArray(textString) && textString.length > 0) {
        textString = textString[0];
      }
      if (typeof textString === 'object' && textString?.text) {
        textString = textString.text;
      }
    }

    if (typeof textString === 'string' && textString) {
      try {
        const textMesh = ctx.fontAtlas.create(textString, {
          size: 0.96,
          font: 'Lora',
          weight: 400,
        });

        if (textMesh) {
          textMesh.position.z = 0.1;
          group.add(textMesh);
        }
      } catch (_err) {
        // Font atlas may not be ready; continue gracefully
      }
    }
  }

  // Apply scene transform
  if (config.scenePosition) {
    const { x, y, z, rotationXYZ, scaleXYZ } = config.scenePosition;

    group.position.set(x || 0, y || 0, z || 0);

    if (rotationXYZ && Array.isArray(rotationXYZ)) {
      group.rotation.order = 'XYZ';
      group.rotation.set(rotationXYZ[0] || 0, rotationXYZ[1] || 0, rotationXYZ[2] || 0);
    }

    if (scaleXYZ && Array.isArray(scaleXYZ)) {
      group.scale.set(scaleXYZ[0] || 1, scaleXYZ[1] || 1, scaleXYZ[2] || 1);
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    toDispose.forEach(resource => {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
